pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(uint8 n, address token, uint256 amount, address actor) public {
        vm.assume(token != address(0));
        vm.assume(token != address(c));
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != token);
        n = uint8(bound(n, 1, 10));

        address[] memory tos = new address[](n);
        uint256[] memory vs = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            tos[i] = actor;
            vs[i] = bound(amount, 0, type(uint256).max / uint256(n));
        }

        bool ok;
        vm.prank(actor);
        try c.transfer(token, tos, vs) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
